//! `rotortypes.go`: the on-disk `rotor.d.ts` editor companion declaring `$env`, `$nameof`,
//! `$keys` and `$file`, byte-for-byte the declarations the compiler injects in memory.

use rotor_support::gopath;

use crate::envdecl::{ENV_DECL_BODY, atomic_write_file};
use crate::macrodecl::MACRO_DECL_BODY;

/// `RotorTypesFileName`
pub const ROTOR_TYPES_FILE_NAME: &str = rotor_tsrs::project::ROTOR_TYPES_FILE_NAME;

/// `RotorTypesFileText`: a generated-file header plus exactly the injected declarations.
#[must_use]
pub fn rotor_types_file_text() -> String {
	format!(
		"// Generated by rotor; do not edit. This file is refreshed automatically.
// Editor types for rotor's compile-time macros: $env, $nameof, $keys,
// and $file. The compiler injects identical declarations in-memory; include
// this file in tsconfig for editor checking. @rbxts/compiler-types supplies
// $getModuleTree. See docs.howmanysmall.com/sloptor/macros/.
{ENV_DECL_BODY}\n{MACRO_DECL_BODY}"
	)
}

/// `WriteRotorTypes`: writes `rotor.d.ts` into `project_dir` when it is missing or stale.
/// Reports whether it was written.
///
/// # Errors
///
/// The atomic write fails.
pub fn write_rotor_types(project_dir: &str) -> std::io::Result<bool> {
	let path = gopath::join(&[project_dir, ROTOR_TYPES_FILE_NAME]);
	let text = rotor_types_file_text();
	if std::fs::read(&path).is_ok_and(|existing| existing == text.as_bytes()) {
		return Ok(false);
	}
	atomic_write_file(&path, text.as_bytes())?;
	Ok(true)
}
